// Базовые элементы JS: const/let, массив, объект, цикл for, if/else
const student = 'Korol Artem II-241';
let counter = 0;

const topics = ['lab4/Korol/basic', 'lab4/Korol/code', 'lab4/Korol/if'];
const meta = { lab: 4, group: 'II-241', student: 'Korol' };

for (let i = 0; i < topics.length; i++) {
  counter++;
}

let verdict;
if (counter === topics.length && meta.lab === 4) {
  verdict = 'all checks passed';
} else {
  verdict = 'something is wrong';
}

return [
  {
    json: {
      payload: student,
      topic: topics[0],
      counter,
      meta,
      verdict,
    },
  },
];
